typedef struct {
    uint32_t *digits;
    size_t len;
    size_t cap;
} BigInt;

static void big_init(BigInt *bi, uint32_t value) {
    bi->cap = 4;
    bi->digits = (uint32_t *)calloc(bi->cap, sizeof(uint32_t));
    if (!bi->digits) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    bi->len = 1;
    bi->digits[0] = value;
}

static void big_reserve(BigInt *bi, size_t needed) {
    if (needed <= bi->cap) {
        return;
    }
    size_t new_cap = bi->cap;
    while (new_cap < needed) {
        new_cap *= 2;
    }
    uint32_t *new_digits = (uint32_t *)realloc(bi->digits, new_cap * sizeof(uint32_t));
    if (!new_digits) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    for (size_t i = bi->cap; i < new_cap; ++i) {
        new_digits[i] = 0;
    }
    bi->digits = new_digits;
    bi->cap = new_cap;
}

static void big_add(BigInt *res, const BigInt *a, const BigInt *b) {
    size_t max_len = a->len > b->len ? a->len : b->len;
    big_reserve(res, max_len + 1);
    uint64_t carry = 0;
    for (size_t i = 0; i < max_len; ++i) {
        uint64_t sum = carry;
        if (i < a->len) {
            sum += a->digits[i];
        }
        if (i < b->len) {
            sum += b->digits[i];
        }
        res->digits[i] = (uint32_t)(sum % BASE);
        carry = sum / BASE;
    }
    if (carry) {
        res->digits[max_len] = (uint32_t)carry;
        res->len = max_len + 1;
    } else {
        res->len = max_len;
    }
}

static void big_swap(BigInt *a, BigInt *b) {
    BigInt tmp = *a;
    *a = *b;
    *b = tmp;
}

static void big_print(const BigInt *bi) {
    if (bi->len == 0) {
        printf("0\n");
        return;
    }
    size_t i = bi->len;
    printf("%u", bi->digits[i - 1]);
    while (i-- > 1) {
        printf("%09u", bi->digits[i - 1]);
    }
    printf("\n");
}

static void big_free(BigInt *bi) {
    free(bi->digits);
    bi->digits = NULL;
    bi->len = 0;
    bi->cap = 0;
}

